-- tipo: SQL | Refs de Colaboradores em 1 ida (CRS,EMPRESAS,CARGOS). Sem params.
SELECT COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CODIGO',t.CODIGO,'NOME',t.NOME,'EMPRESA_ID',t.EMPRESA_ID,'ATIVO',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'CNPJ',t.CNPJ,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM)) FROM EMPRESA t WHERE 1=1),JSON_ARRAY()) AS EMPRESAS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'SALARIO_MEDIO',t.SALARIO_MEDIO,'ATIVO',t.ATIVO)) FROM CARGO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CARGOS